enum zts_errno_t {
  /// Operation not permitted
  ZTS_EPERM(1),

  /// No such file or directory
  ZTS_ENOENT(2),

  /// No such process
  ZTS_ESRCH(3),

  /// Interrupted system call
  ZTS_EINTR(4),

  /// I/O error
  ZTS_EIO(5),

  /// No such device or address
  ZTS_ENXIO(6),

  /// Bad file number
  ZTS_EBADF(9),

  /// Try again
  ZTS_EAGAIN(11),

  /// Out of memory
  ZTS_ENOMEM(12),

  /// Permission denied
  ZTS_EACCES(13),

  /// Bad address
  ZTS_EFAULT(14),

  /// Device or resource busy
  ZTS_EBUSY(16),

  /// File exists
  ZTS_EEXIST(17),

  /// No such device
  ZTS_ENODEV(19),

  /// Invalid argument
  ZTS_EINVAL(22),

  /// File table overflow
  ZTS_ENFILE(23),

  /// Too many open files
  ZTS_EMFILE(24),

  /// Function not implemented
  ZTS_ENOSYS(38),

  /// Socket operation on non-socket
  ZTS_ENOTSOCK(88),

  /// Destination address required
  ZTS_EDESTADDRREQ(89),

  /// Message too long
  ZTS_EMSGSIZE(90),

  /// Protocol wrong type for socket
  ZTS_EPROTOTYPE(91),

  /// Protocol not available
  ZTS_ENOPROTOOPT(92),

  /// Protocol not supported
  ZTS_EPROTONOSUPPORT(93),

  /// Socket type not supported
  ZTS_ESOCKTNOSUPPORT(94),

  /// Operation not supported on transport endpoint
  ZTS_EOPNOTSUPP(95),

  /// Protocol family not supported
  ZTS_EPFNOSUPPORT(96),

  /// Address family not supported by protocol
  ZTS_EAFNOSUPPORT(97),

  /// Address already in use
  ZTS_EADDRINUSE(98),

  /// Cannot assign requested address
  ZTS_EADDRNOTAVAIL(99),

  /// Network is down
  ZTS_ENETDOWN(100),

  /// Network is unreachable
  ZTS_ENETUNREACH(101),

  /// Software caused connection abort
  ZTS_ECONNABORTED(103),

  /// Connection reset by peer
  ZTS_ECONNRESET(104),

  /// No buffer space available
  ZTS_ENOBUFS(105),

  /// Transport endpoint is already connected
  ZTS_EISCONN(106),

  /// Transport endpoint is not connected
  ZTS_ENOTCONN(107),

  /// Connection timed out
  ZTS_ETIMEDOUT(110),

  /// Connection refused
  ZTS_ECONNREFUSED(111),

  /// No route to host
  ZTS_EHOSTUNREACH(113),

  /// Operation already in progress
  ZTS_EALREADY(114),

  /// Operation now in progress
  ZTS_EINPROGRESS(115);

  /// Operation would block
  static const ZTS_EWOULDBLOCK = ZTS_EAGAIN;

  final int value;
  const zts_errno_t(this.value);

  static zts_errno_t fromValue(int value) => switch (value) {
    1 => ZTS_EPERM,
    2 => ZTS_ENOENT,
    3 => ZTS_ESRCH,
    4 => ZTS_EINTR,
    5 => ZTS_EIO,
    6 => ZTS_ENXIO,
    9 => ZTS_EBADF,
    11 => ZTS_EAGAIN,
    12 => ZTS_ENOMEM,
    13 => ZTS_EACCES,
    14 => ZTS_EFAULT,
    16 => ZTS_EBUSY,
    17 => ZTS_EEXIST,
    19 => ZTS_ENODEV,
    22 => ZTS_EINVAL,
    23 => ZTS_ENFILE,
    24 => ZTS_EMFILE,
    38 => ZTS_ENOSYS,
    88 => ZTS_ENOTSOCK,
    89 => ZTS_EDESTADDRREQ,
    90 => ZTS_EMSGSIZE,
    91 => ZTS_EPROTOTYPE,
    92 => ZTS_ENOPROTOOPT,
    93 => ZTS_EPROTONOSUPPORT,
    94 => ZTS_ESOCKTNOSUPPORT,
    95 => ZTS_EOPNOTSUPP,
    96 => ZTS_EPFNOSUPPORT,
    97 => ZTS_EAFNOSUPPORT,
    98 => ZTS_EADDRINUSE,
    99 => ZTS_EADDRNOTAVAIL,
    100 => ZTS_ENETDOWN,
    101 => ZTS_ENETUNREACH,
    103 => ZTS_ECONNABORTED,
    104 => ZTS_ECONNRESET,
    105 => ZTS_ENOBUFS,
    106 => ZTS_EISCONN,
    107 => ZTS_ENOTCONN,
    110 => ZTS_ETIMEDOUT,
    111 => ZTS_ECONNREFUSED,
    113 => ZTS_EHOSTUNREACH,
    114 => ZTS_EALREADY,
    115 => ZTS_EINPROGRESS,
    _ => throw ArgumentError('Unknown value for zts_errno_t: $value'),
  };

  @override
  String toString() {
    if (this == ZTS_EAGAIN)
      return "zts_errno_t.ZTS_EAGAIN, zts_errno_t.ZTS_EWOULDBLOCK";
    return super.toString();
  }
}

/// Common error return values
enum zts_error_t {
  /// No error
  ZTS_ERR_OK(0),

  /// Socket error, see `zts_errno`
  ZTS_ERR_SOCKET(-1),

  /// This operation is not allowed at this time. Or possibly the node hasn't
  /// been started
  ZTS_ERR_SERVICE(-2),

  /// Invalid argument
  ZTS_ERR_ARG(-3),

  /// No result (not necessarily an error)
  ZTS_ERR_NO_RESULT(-4),

  /// Consider filing a bug report
  ZTS_ERR_GENERAL(-5);

  final int value;
  const zts_error_t(this.value);

  static zts_error_t fromValue(int value) => switch (value) {
    0 => ZTS_ERR_OK,
    -1 => ZTS_ERR_SOCKET,
    -2 => ZTS_ERR_SERVICE,
    -3 => ZTS_ERR_ARG,
    -4 => ZTS_ERR_NO_RESULT,
    -5 => ZTS_ERR_GENERAL,
    _ => throw ArgumentError('Unknown value for zts_error_t: $value'),
  };
}

